server01.mjs<pre><code>import { ApolloServer } from "@apollo/server";
import { startStandaloneServer } from "@apollo/server/standalone";
import { scryptSync, randomBytes, timingSafeEqual } from "node:crypto";
import { issueToken, viewerFromHeader } from "./auth.js";

// Demo user store. Passwords are stored as scrypt hashes, never in plain text.
const hash = (pw, salt = randomBytes(16)) =&gt; ({ salt, key: scryptSync(pw, salt, 32) });
const users = new Map([
  ["1", { id: "1", email: "ada@example.com", role: "ADMIN", pw: hash("correct horse") }],
  ["2", { id: "2", email: "bob@example.com", role: "MEMBER", pw: hash("battery staple") }],
]);
const byEmail = (email) =&gt; [...users.values()].find((u) =&gt; u.email === email);

const typeDefs = /* GraphQL */ `
  type Query { viewer: User, publicCatalogSize: Int! }
  type Mutation { login(email: String!, password: String!): LoginPayload! }
  type User { id: ID! email: String! role: String! }
  type LoginPayload { token: String, user: User, error: String }
`;

const resolvers = {
  Query: {
    viewer: (_, __, { viewer }) =&gt; viewer,
    publicCatalogSize: () =&gt; 8,
  },
  Mutation: {
    login: async (_, { email, password }) =&gt; {
      const user = byEmail(email);
      const ok = user &amp;&amp; timingSafeEqual(scryptSync(password, user.pw.salt, 32), user.pw.key);
      if (!ok) return { token: null, user: null, error: "Email or password is incorrect." };
      return { token: await issueToken(user), user, error: null };
    },
  },
};

const server = new ApolloServer({ typeDefs, resolvers, includeStacktraceInErrorResponses: false });
const { url } = await startStandaloneServer(server, {
  listen: { port: 4001 },
  context: async ({ req }) =&gt; ({ viewer: await viewerFromHeader(req.headers.authorization, users) }),
});
console.log(`ready at ${url}`);
</code></pre> <p>Passwords are stored as scrypt hashes with a per-user random salt (<code>node:crypto</code>), and compared with <code>timingSafeEqual</code>, which takes the same time regardless of where two buffers first differ. Login failures are returned as data (Level 2 · 08), and the message doesn't say which of email or password was wrong.</p>

authz.js<pre><code>import { GraphQLError } from "graphql";

// All rules in one place, as plain functions of (viewer, object).
export const can = {
  readPost: (viewer, post) =&gt;
    post.visibility === "PUBLIC" || (viewer &amp;&amp; (viewer.role === "ADMIN" || viewer.id === post.authorId)),
  editPost: (viewer, post) =&gt; viewer &amp;&amp; (viewer.role === "ADMIN" || viewer.id === post.authorId),
  seeEmail: (viewer, user) =&gt; viewer &amp;&amp; (viewer.role === "ADMIN" || viewer.id === user.id),
  listUsers: (viewer) =&gt; viewer?.role === "ADMIN",
};

export const forbidden = (message = "Not allowed") =&gt;
  new GraphQLError(message, { extensions: { code: "FORBIDDEN" } });
export const unauthenticated = () =&gt;
  new GraphQLError("You must be logged in", { extensions: { code: "UNAUTHENTICATED" } });
</code></pre> <p>Keeping every rule in one module, as pure functions of <code>(viewer, object)</code>, has three benefits: the rules are unit-testable without GraphQL, they can be reused by REST endpoints or background jobs, and reviewing "who can read a post?" means reading one line.</p>

server02.mjs<pre><code>import { ApolloServer } from "@apollo/server";
import { makeExecutableSchema } from "@graphql-tools/schema";
import { can, forbidden, unauthenticated } from "./authz.js";

const users = [
  { id: "u1", name: "Ada", email: "ada@example.com", role: "ADMIN" },
  { id: "u2", name: "Bob", email: "bob@example.com", role: "MEMBER" },
  { id: "u3", name: "Cy", email: "cy@example.com", role: "MEMBER" },
];
const posts = [
  { id: "p1", title: "Hello world", visibility: "PUBLIC", authorId: "u2" },
  { id: "p2", title: "Bob's draft", visibility: "PRIVATE", authorId: "u2" },
  { id: "p3", title: "Cy's notes", visibility: "PRIVATE", authorId: "u3" },
];

export const schema = makeExecutableSchema({
  typeDefs: /* GraphQL */ `
    type Query {
      posts: [Post!]!
      post(id: ID!): Post
      users: [User!]!
    }
    type Mutation { renamePost(id: ID!, title: String!): Post }
    type Post { id: ID! title: String! visibility: String! author: User! }
    type User {
      id: ID!
      name: String!
      "Visible to the user themselves and to admins; null otherwise."
      email: String
    }
  `,
  resolvers: {
    Query: {
      // object-level: filter what the viewer may read
      posts: (_, __, { viewer }) =&gt; posts.filter((p) =&gt; can.readPost(viewer, p)),
      // a hidden object looks exactly like a missing one
      post: (_, { id }, { viewer }) =&gt; {
        const p = posts.find((x) =&gt; x.id === id);
        return p &amp;&amp; can.readPost(viewer, p) ? p : null;
      },
      // operation-level: whole field requires a role
      users: (_, __, { viewer }) =&gt; {
        if (!viewer) throw unauthenticated();
        if (!can.listUsers(viewer)) throw forbidden("Only admins can list users");
        return users;
      },
    },
    Mutation: {
      renamePost: (_, { id, title }, { viewer }) =&gt; {
        if (!viewer) throw unauthenticated();
        const p = posts.find((x) =&gt; x.id === id);
        if (!p || !can.readPost(viewer, p)) return null;          // don't reveal it exists
        if (!can.editPost(viewer, p)) throw forbidden("You can only rename your own posts");
        p.title = title;
        return p;
      },
    },
    Post: { author: (p) =&gt; users.find((u) =&gt; u.id === p.authorId) },
    // field-level: redact instead of failing the whole object
    User: { email: (u, _, { viewer }) =&gt; (can.seeEmail(viewer, u) ? u.email : null) },
  },
});

const server = new ApolloServer({ schema, includeStacktraceInErrorResponses: false });
const as = (userId) =&gt; ({ viewer: users.find((u) =&gt; u.id === userId) ?? null });

async function run(label, who, query) {
  const res = await server.executeOperation({ query }, { contextValue: as(who) });
  console.log(`--- ${label} (as ${who ?? "anonymous"})\n${JSON.stringify(res.body.singleResult)}`);
}

const LIST = `{ posts { id title author { name email } } }`;
await run("post list", null, LIST);
await run("post list", "u2", LIST);
await run("post list", "u1", LIST);
await run("someone else's private post", "u2", `{ post(id: "p3") { title } }`);
await run("a post that doesn't exist", "u2", `{ post(id: "p999") { title } }`);
await run("users", null, `{ users { name } }`);
await run("users", "u2", `{ users { name } }`);
await run("users", "u1", `{ users { name email } }`);
await run("rename own post", "u2", `mutation { renamePost(id: "p2", title: "Bob's post") { title } }`);
await run("rename someone else's public post", "u3", `mutation { renamePost(id: "p1", title: "pwned") { title } }`);
await run("rename someone else's private post", "u3", `mutation { renamePost(id: "p2", title: "pwned") { title } }`);
</code></pre>

server04.mjs<pre><code>import { createServer } from "node:http";
import { WebSocketServer } from "ws";
import { useServer } from "graphql-ws/use/ws";
import { makeExecutableSchema } from "@graphql-tools/schema";
import { PubSub } from "./pubsub.js";

export const pubsub = new PubSub();
const messages = [];

export const schema = makeExecutableSchema({
  typeDefs: /* GraphQL */ `
    type Message { id: ID! room: String! author: String! text: String! }
    type Query { messages(room: String!): [Message!]! }
    type Mutation { post(room: String!, text: String!): Message! }
    type Subscription {
      messagePosted(room: String!): Message!
      tick(count: Int!): Int!
    }
  `,
  resolvers: {
    Query: { messages: (_, { room }) =&gt; messages.filter((m) =&gt; m.room === room) },
    Mutation: {
      post: (_, { room, text }, { user }) =&gt; {
        const msg = { id: String(messages.length + 1), room, author: user ?? "anonymous", text };
        messages.push(msg);
        pubsub.publish(`room:${room}`, msg); // publish AFTER the write succeeds
        return msg;
      },
    },
    Subscription: {
      messagePosted: {
        // subscribe returns an AsyncIterable; each value becomes one event
        subscribe: (_, { room }) =&gt; pubsub.subscribe(`room:${room}`),
        resolve: (payload) =&gt; payload,
      },
      tick: {
        subscribe: async function* (_, { count }) {
          for (let i = 1; i &lt;= count; i++) {
            await new Promise((r) =&gt; setTimeout(r, 50));
            yield { tick: i };
          }
        },
      },
    },
  },
});

export function start(port) {
  const httpServer = createServer((req, res) =&gt; { res.writeHead(404).end(); });
  const wss = new WebSocketServer({ server: httpServer, path: "/graphql" });
  const handle = useServer(
    {
      schema,
      // connectionParams arrive in the first message (connection_init), not as HTTP headers
      context: (ctx) =&gt; ({ user: ctx.connectionParams?.user ?? null }),
      onConnect: (ctx) =&gt; {
        if (ctx.connectionParams?.token === "bad") return false; // reject the connection
        return true;
      },
      onSubscribe: (_ctx, id, payload) =&gt; console.log(`  [server] subscribe ${id.slice(0, 8)}: ${payload.query.replace(/\s+/g, " ").slice(0, 40)}`),
      onComplete: (_ctx, id) =&gt; console.log(`  [server] complete ${id.slice(0, 8)}`),
    },
    wss,
  );
  return new Promise((resolve) =&gt; httpServer.listen(port, () =&gt; resolve({ httpServer, wss, handle })));
}
</code></pre> <p>Things to notice:</p> <ul> <li><code>messagePosted.subscribe</code> builds the topic name from the <code>room</code> argument, so each subscriber   only receives messages for its room — the filtering happens by topic, not by checking every   message against every subscriber.</li> <li><code>tick</code> shows the other common pattern: <code>subscribe</code> is an async generator. When it   returns, the subscription completes. No <code>resolve</code> is needed because each yielded value has a   <code>tick</code> key matching the field name.</li> <li>The mutation publishes after the write. Publishing first risks notifying subscribers   about a change that then fails.</li> <li>WebSocket context comes from <code>connectionParams</code> — a JSON payload the client sends in its first   message. Browsers can't set custom headers on WebSocket connections, so tokens usually travel   this way. <code>onConnect</code> returning <code>false</code> rejects the connection.</li> </ul>

client04.mjs<pre><code>import WebSocket from "ws";
import { createClient } from "graphql-ws";
import { start, pubsub } from "./server04.mjs";

const { httpServer, handle } = await start(4310);
const url = "ws://localhost:4310/graphql";

const alice = createClient({ url, webSocketImpl: WebSocket, connectionParams: { user: "alice" }, lazy: false });
const bob = createClient({ url, webSocketImpl: WebSocket, connectionParams: { user: "bob" }, lazy: false });

// 1. A finite subscription, consumed with the async-iterator API
const ticks = [];
for await (const result of alice.iterate({ query: "subscription Ticks { tick(count: 3) }" })) ticks.push(result.data.tick);
console.log("ticks:", ticks);

// 2. Room-filtered chat: bob listens to #general only
const received = [];
const stop = bob.subscribe(
  { query: `subscription Room { messagePosted(room: "general") { author text } }` },
  { next: (r) =&gt; received.push(r.data.messagePosted), error: (e) =&gt; console.log("error", e), complete: () =&gt; console.log("  [bob] complete") },
);
await new Promise((r) =&gt; setTimeout(r, 100)); // let the subscription register
console.log("listeners on room:general:", pubsub.listenerCount("room:general"));

const mutate = (client, query) =&gt; new Promise((resolve, reject) =&gt; {
  let result;
  client.subscribe({ query }, { next: (r) =&gt; (result = r), error: reject, complete: () =&gt; resolve(result) });
});
await mutate(alice, `mutation { post(room: "general", text: "hi bob") { id } }`);
await mutate(alice, `mutation { post(room: "random", text: "not for bob") { id } }`);
await mutate(alice, `mutation { post(room: "general", text: "still there?") { id } }`);
await new Promise((r) =&gt; setTimeout(r, 100));
console.log("bob received:", JSON.stringify(received));

stop(); // client sends "complete"; server calls return() on the iterator
await new Promise((r) =&gt; setTimeout(r, 100));
console.log("listeners after unsubscribe:", pubsub.listenerCount("room:general"));

// 3. A rejected connection
const evil = createClient({ url, webSocketImpl: WebSocket, connectionParams: { token: "bad" }, retryAttempts: 0 });
await new Promise((resolve) =&gt; evil.subscribe({ query: "subscription { tick(count: 1) }" },
  { next() {}, complete: resolve, error: (e) =&gt; { console.log("rejected:", e.code, e.reason); resolve(); } }));

// 4. Validation errors arrive before any event
await new Promise((resolve) =&gt; alice.subscribe({ query: "subscription { nope }" },
  { next() {}, complete: resolve, error: (e) =&gt; { console.log("invalid:", JSON.stringify(e)); resolve(); } }));

await alice.dispose(); await bob.dispose(); await evil.dispose();
await handle.dispose();
httpServer.close();
