store.js<pre><code>// In-memory data for the project. Swap for a database without touching resolvers.
export function createStore() {
  return {
    users: new Map([
      ["u1", { id: "u1", name: "Ada" }],
      ["u2", { id: "u2", name: "Bob" }],
      ["u3", { id: "u3", name: "Eve" }],
    ]),
    boards: new Map([["b1", { id: "b1", name: "Launch", memberIds: ["u1", "u2"] }]]),
