subgraphs.js<pre><code>import { buildSubgraphSchema } from "@apollo/subgraph";
import { parse } from "graphql";

const FED = `extend schema @link(url: "https://specs.apollo.dev/federation/v2.3", import: ["@key", "@shareable", "@external", "@requires"])`;

// ---------- products subgraph: owns Product
const products = [
  { upc: "p1", name: "Desk lamp", priceCents: 2499, weightGrams: 900 },
  { upc: "p2", name: "Bookshelf", priceCents: 8900, weightGrams: 15000 },
];
export const productsSchema = buildSubgraphSchema([{
  typeDefs: parse(`${FED}
    type Query { products: [Product!]! product(upc: ID!): Product }
    type Product @key(fields: "upc") {
      upc: ID!
      name: String!
      priceCents: Int!
      weightGrams: Int!
    }
  `),
  resolvers: {
    Query: {
      products: () =&gt; products,
      product: (_, { upc }) =&gt; products.find((p) =&gt; p.upc === upc) ?? null,
    },
    Product: {
      // Called when another subgraph's result needs Product fields owned here.
      __resolveReference: (ref) =&gt; products.find((p) =&gt; p.upc === ref.upc) ?? null,
    },
  },
}]);

// ---------- reviews subgraph: owns Review, adds Product.reviews
const reviews = [
  { id: "r1", productUpc: "p1", stars: 5, body: "Bright and sturdy." },
  { id: "r2", productUpc: "p1", stars: 3, body: "Cable is short." },
  { id: "r3", productUpc: "p2", stars: 4, body: "Took an hour to build." },
];
export const reviewsSchema = buildSubgraphSchema([{
  typeDefs: parse(`${FED}
    type Query { latestReviews: [Review!]! }
    type Review { id: ID! stars: Int! body: String! product: Product! }
    type Product @key(fields: "upc") {
      upc: ID!
      reviews: [Review!]!
      averageStars: Float
    }
  `),
  resolvers: {
    Query: { latestReviews: () =&gt; reviews.slice().reverse() },
    Review: { product: (r) =&gt; ({ __typename: "Product", upc: r.productUpc }) }, // a reference
    Product: {
      __resolveReference: (ref) =&gt; ref, // nothing stored per product here; the key is enough
      reviews: (p) =&gt; reviews.filter((r) =&gt; r.productUpc === p.upc),
      averageStars: (p) =&gt; {
        const rs = reviews.filter((r) =&gt; r.productUpc === p.upc);
        return rs.length ? rs.reduce((s, r) =&gt; s + r.stars, 0) / rs.length : null;
      },
    },
  },
}]);
</code></pre> <p>Points to note:</p> <ul> <li><code>extend schema @link(url: ".../federation/v2.3", import: [...])</code> opts the SDL into Federation 2   and imports the directives used.</li> <li><code>Review.product</code> returns <code>{ __typename: "Product", upc }</code> — a reference. The reviews   subgraph doesn't know a product's name or price, and doesn't pretend to; the router will fill   those in from the products subgraph.</li> <li><code>Product.__resolveReference</code> in each subgraph is called with a representation   (<code>{ __typename, upc }</code>) and returns the subgraph's own object for that key.</li> </ul>

concepts03.mjs<pre><code>import { graphql, printSchema } from "graphql";
import { productsSchema, reviewsSchema } from "./subgraphs.js";

const run = async (label, schema, source, variableValues) =&gt;
  console.log(`--- ${label}\n${JSON.stringify(await graphql({ schema, source, variableValues }))}`);

// 1. What the subgraph adds to its own schema
console.log("root Query fields in reviews subgraph:", Object.keys(reviewsSchema.getQueryType().getFields()).join(", "));
console.log("_Entity union members:", reviewsSchema.getType("_Entity").getTypes().map((t) =&gt; t.name).join(", "));

// 2. _service { sdl }: the subgraph's SDL *with* federation directives
const sdl = (await graphql({ schema: reviewsSchema, source: "{ _service { sdl } }" })).data._service.sdl;
console.log("\n--- reviews _service.sdl (Product part)\n" + sdl.split("\n").filter((l, i, a) =&gt; {
  const start = a.findIndex((x) =&gt; x.startsWith("type Product"));
  return i &gt;= start &amp;&amp; i &lt;= start + 4;
}).join("\n"));

// 3. _entities: how a router asks a subgraph about objects it doesn't own
const ENTITIES = `query($reps: [_Any!]!) { _entities(representations: $reps) { ... on Product { upc reviews { stars } averageStars } } }`;
await run("reviews._entities for two products", reviewsSchema, ENTITIES,
  { reps: [{ __typename: "Product", upc: "p2" }, { __typename: "Product", upc: "p1" }] });

await run("products._entities resolving references", productsSchema,
  `query($reps: [_Any!]!) { _entities(representations: $reps) { ... on Product { upc name priceCents } } }`,
  { reps: [{ __typename: "Product", upc: "p1" }, { __typename: "Product", upc: "zzz" }] });

// 4. A subgraph alone can only answer its own part
await run("reviews subgraph alone", reviewsSchema, `{ latestReviews { stars product { upc } } }`);
</code></pre> <pre><code>$ node concepts03.mjs
root Query fields in reviews subgraph: latestReviews, _entities, _service
_Entity union members: Product
</code></pre> <p>Two root fields appeared that we never wrote:</p> <ul> <li><code>_service: _Service!</code> returns <code>{ sdl }</code>, the subgraph's SDL including federation   directives. Standard introspection can't express applied directives like <code>@key</code>   (Level 3 · 03), so federation needs this side channel.</li> <li><code>_entities(representations: [_Any!]!): [_Entity]!</code> — the entity-fetching entry point.   <code>_Entity</code> is a union of every type with a <code>@key</code>.</li> </ul>

gateway04.mjs<pre><code>import { ApolloServer } from "@apollo/server";
import { startStandaloneServer } from "@apollo/server/standalone";
import { ApolloGateway, IntrospectAndCompose } from "@apollo/gateway";
import { prettyFormatQueryPlan } from "@apollo/query-planner";
import { productsSchema, reviewsSchema } from "./subgraphs.js";

// Log every request each subgraph receives, so we can see the router's traffic.
const subgraphLog = [];
const logPlugin = (name) =&gt; ({
  async requestDidStart({ request }) {
    const q = request.query.replace(/\s+/g, " ").trim();
    subgraphLog.push(`${name}: ${q.length &gt; 110 ? q.slice(0, 107) + "..." : q}` +
      (request.variables?.representations ? `  [${request.variables.representations.length} representations]` : ""));
  },
});

async function startSubgraph(name, schema, port) {
  const server = new ApolloServer({ schema, plugins: [logPlugin(name)] });
  const { url } = await startStandaloneServer(server, { listen: { port } });
  return { server, url };
}
const products = await startSubgraph("products", productsSchema, 4401);
const reviews = await startSubgraph("reviews", reviewsSchema, 4402);

let lastPlan = "";
const gateway = new ApolloGateway({
  // Dev-only: introspect running subgraphs and compose at startup.
  supergraphSdl: new IntrospectAndCompose({
    subgraphs: [
      { name: "products", url: products.url },
      { name: "reviews", url: reviews.url },
    ],
  }),
  experimental_didResolveQueryPlan: ({ queryPlan }) =&gt; { lastPlan = prettyFormatQueryPlan(queryPlan); },
});
const router = new ApolloServer({ gateway });
const { url } = await startStandaloneServer(router, { listen: { port: 4400 } });
console.log(`router at ${url}`);

async function query(label, q) {
  subgraphLog.length = 0;
  const res = await fetch(url, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ query: q }) });
  console.log(`\n=== ${label}\n${JSON.stringify(await res.json())}`);
  console.log("--- query plan\n" + lastPlan);
  console.log("--- subgraph requests\n" + subgraphLog.join("\n"));
}

await query("one subgraph", `{ products { name priceCents } }`);
await query("products with their reviews", `{ products { name reviews { stars } averageStars } }`);
await query("reviews with product names", `{ latestReviews { stars product { name } } }`);

await router.stop(); await products.server.stop(); await reviews.server.stop();
</code></pre> <p><code>subgraphs.js</code> is unchanged from lesson 03. Each subgraph runs on its own Apollo Server with a logging plugin; the router is an Apollo Server constructed with <code>gateway</code> instead of a schema. <code>experimental_didResolveQueryPlan</code> captures the plan for each operation, and the query planner's <code>prettyFormatQueryPlan</code> prints it.</p> <p>On start, Apollo Server printed this once per subgraph:</p> <pre><code>Enabling inline tracing for this subgraph. To disable, use ApolloServerPluginInlineTraceDisabled.
</code></pre> <p>Apollo Server detects a federated schema and enables inline tracing: when the router asks, the subgraph returns per-field timing in the response extensions so the router can assemble a cross-subgraph trace. It's harmless locally.</p>

errors06.mjs<pre><code>import { randomUUID } from "node:crypto";
import { ApolloServer } from "@apollo/server";
import { unwrapResolverError } from "@apollo/server/errors";
import { GraphQLError } from "graphql";
import { createYoga, createSchema } from "graphql-yoga";

const typeDefs = `type Query { ok: String, notFound: String, dbDown: String, bug: String }`;
const resolvers = {
  Query: {
    ok: () =&gt; "fine",
    notFound: () =&gt; { throw new GraphQLError("Order 42 not found", { extensions: { code: "NOT_FOUND" } }); },
    dbDown: () =&gt; { throw new Error('connect ECONNREFUSED 10.0.3.17:5432 (user "orders_rw")'); },
    bug: () =&gt; { const order = undefined; return order.total; },
  },
};
const QUERY = "{ ok notFound dbDown bug }";

// 1. Apollo Server defaults
const plain = new ApolloServer({ typeDefs, resolvers, includeStacktraceInErrorResponses: false });
const r1 = await plain.executeOperation({ query: QUERY });
console.log("== Apollo, default formatting");
for (const e of r1.body.singleResult.errors) console.log(" ", JSON.stringify(e));

// 2. Apollo Server with masking: expected errors pass through, everything else is replaced
const SAFE_CODES = new Set(["NOT_FOUND", "BAD_USER_INPUT", "UNAUTHENTICATED", "FORBIDDEN",
  "GRAPHQL_VALIDATION_FAILED", "GRAPHQL_PARSE_FAILED", "BAD_REQUEST", "PERSISTED_QUERY_NOT_FOUND"]);
const logged = [];
const masked = new ApolloServer({
  typeDefs, resolvers, includeStacktraceInErrorResponses: false,
  formatError(formatted, error) {
    if (SAFE_CODES.has(formatted.extensions?.code)) return formatted;
    const original = unwrapResolverError(error);
    const errorId = randomUUID().slice(0, 8);
    logged.push({ errorId, path: formatted.path?.join("."), message: original.message, stack: original.stack?.split("\n")[1]?.trim() });
    return { message: "Internal server error", path: formatted.path, extensions: { code: "INTERNAL_SERVER_ERROR", errorId } };
  },
});
const r2 = await masked.executeOperation({ query: QUERY });
console.log("\n== Apollo with formatError masking — client sees");
for (const e of r2.body.singleResult.errors) console.log(" ", JSON.stringify(e));
console.log("data still returned:", JSON.stringify(r2.body.singleResult.data));
console.log("server log:");
for (const l of logged) console.log(" ", JSON.stringify(l));

// 3. GraphQL Yoga masks unexpected errors by default
const yoga = createYoga({ schema: createSchema({ typeDefs, resolvers }), logging: false });
const res = await yoga.fetch("http://yoga/graphql", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ query: QUERY }) });
console.log("\n== Yoga default");
for (const e of (await res.json()).errors) console.log(" ", JSON.stringify(e));
</code></pre> <ul> <li><code>notFound</code> throws a <code>GraphQLError</code> with a code — an expected error the client should see.</li> <li><code>dbDown</code> throws the kind of message a PostgreSQL client produces when it can't connect — an   infrastructure failure.</li> <li><code>bug</code> dereferences <code>undefined</code> — a programming error.</li> </ul>

